 * Webhook endpoint management and the bridge from `webhook.delivery_requested` to the delivery queue.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, wouldExceedLimit
 */
import { createHmac } from "node:crypto";
import { wouldExceedLimit } from "@/config/plan-limits";
import { subscribe } from "@/lib/event-bus";
import { isEnabled } from "@/lib/feature-flags";
import { randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { requireFound, webhookResource } from "./_support";
import type {
  CreateWebhookInput,
  DeleteWebhookInput,
  UpdateWebhookInput,
} from "@/schemas/webhook";
import type { WebhookEndpointRow } from "@/server/db/schema/webhooks";
import type { OrgId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { FlagContext } from "@/types/feature-flag";
import type { Actor } from "@/types/member";

/** Length in bytes of a generated endpoint signing secret. */
const SECRET_BYTES = 32;

export async function listWebhooks(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly WebhookEndpointRow[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "webhook:manage", webhookResource(orgId, null));
  return webhookRepo.listEndpoints(orgId);
}

/**
 * Creating an endpoint is gated twice: the `webhooks` flag has to be on for
 * the org's plan, and the plan's endpoint count must have room. A secret is
 * minted here and never regenerated — rotating it means deleting the endpoint.
 */
export async function createWebhook(
  actor: Actor,
  input: CreateWebhookInput,
): Promise<WebhookEndpointRow> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "webhook:manage", webhookResource(input.orgId, null));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (!isEnabled("webhooks", flagContextFor(actor, org.plan, org.settings.enabledFlagOverrides))) {
    throw new Error("Outgoing webhooks are not included in this plan");
  }

/**
 * Query-time search plus the write-time index maintenance driven by `search.reindex_requested`.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, consumeRateLimit
 */
/**
 * Scans for issues past `dueAt` and emits `issue.overdue`, which the notification fan-out turns into alerts.
 *
 * Must call (do not reimplement): emit, shouldFilterArchived
 */
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import { shouldFilterArchived } from "@/lib/soft-delete";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";

/** How many organizations one pass sweeps. */
const ORG_BATCH = 50;

/** Archived issues are never overdue — an archived issue has no due date. */
const LIVE_ONLY = {} as const;

const logger = createLogger("overdue-issue-job");

/**
 * Issues already announced this process's lifetime. A later sweep still
 * finds a still-open, still-overdue issue — this is what keeps the job from
 * re-emitting `issue.overdue` for it on every pass.
 */
const reported = new Set<string>();

/** Test-only: clears the reported set so a fresh scenario starts empty. */
export function resetOverdueTracking(): void {
  reported.clear();
}

/**
 * Publishes one `issue.overdue` per still-open, past-due issue. The job owns
 * no notification logic: it announces the fact, and whoever cares (in-app
 * alerts, the digest, webhooks) reacts on the bus.
 */
export async function runOverdueIssueJob(now: Date): Promise<JobResult> {
  return runJob("overdue-issues", async (result) => {
    if (!shouldFilterArchived(LIVE_ONLY)) {
      logger.warn("archive scope misconfigured; skipping sweep", {});
      return;
    }

    const stamp = toIsoTimestamp(now);
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const overdue = await issueRepo.listOverdueIssues(orgId, stamp);

      for (const issue of overdue) {
        if (issue.dueAt === null) continue;
        if (reported.has(issue.id)) continue;

        try {
          await emit("issue.overdue", {
            orgId,
            actorId: null,
            occurredAt: stamp,
            issueId: issue.id,
            projectId: issue.projectId,
            dueAt: issue.dueAt,
            assigneeId: issue.assigneeId,
          });
          reported.add(issue.id);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to announce overdue issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }
    }
  });
}
/**
 * Explicit project membership for `private` projects.
 */
import { and, eq } from "drizzle-orm";
import { getDb, projectMembers } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { brandId } from "./_mappers";
import { orgPredicate } from "./base-repository";
import type { OrgId, ProjectId, UserId } from "@/types/common";

export async function listProjectMemberIds(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly UserId[]> {
  const rows = getDb()
    .select({ userId: projectMembers.userId })
    .from(projectMembers)
    .where(
      and(
        orgPredicate(projectMembers.orgId, orgId),
        eq(projectMembers.projectId, projectId),
      ),
    )
    .all();
  return rows.map((row) => brandId<UserId>(row.userId));
}

/** Idempotent: re-adding an existing member is a no-op, not a conflict. */
export async function addProjectMember(
  orgId: OrgId,
  projectId: ProjectId,
  userId: UserId,
): Promise<void> {
  if (await isProjectMember(orgId, projectId, userId)) return;

  getDb()
    .insert(projectMembers)
    .values({
      orgId,
      projectId,
      userId,
      addedAt: toIsoTimestamp(new Date()),
    })
    .run();
}

export async function removeProjectMember(
  orgId: OrgId,
  projectId: ProjectId,
  userId: UserId,
): Promise<void> {
  getDb()
    .delete(projectMembers)
    .where(
      and(
        orgPredicate(projectMembers.orgId, orgId),
        eq(projectMembers.projectId, projectId),
        eq(projectMembers.userId, userId),
      ),
    )

