export type NotificationPayload = {
  title: string;
  body: string;
  href: string;
  actorId: UserId | null;
  /** The project the notification is about. Omit it for notifications that are not about a project. */
  projectId?: ProjectId | null;
};

/** Channels used when a recipient has never touched their preferences. */
const DEFAULT_CHANNELS: readonly NotificationChannel[] = ["in_app", "email"];

/**
 * Kinds addressed to one recipient personally. A recipient who muted the
 * project still gets these, just never by email; every other kind about a
 * muted project is dropped for them.
 */
const PERSONAL_KINDS: ReadonlySet<NotificationKind> = new Set<NotificationKind>([
  "issue_assigned",
  "comment_mention",
  "issue_overdue",
]);

/**
 * Writes one notification row per recipient, each with the channel set that
 * recipient's preferences allow. A recipient who has muted every channel is
 * skipped entirely rather than given a row nobody will ever see. When the
 * payload names a project, a recipient who muted that project is handled by
 * the mute rules on top of their preferences.
 */
export async function notify(
  orgId: OrgId,
  kind: NotificationKind,
  recipients: readonly UserId[],
  payload: NotificationPayload,
): Promise<readonly Notification[]> {
  if (recipients.length === 0) return [];

  const org = await orgRepo.findOrgById(orgId);
  const flags: FlagContext = {
    orgId,
    userId: payload.actorId,
    plan: org?.plan ?? "free",
    role: null,
    overrides: org?.settings.enabledFlagOverrides,
  };

  const projectId = payload.projectId ?? null;
  const recipientIds = [...new Set(recipients)];
  const mutedBy =
    projectId === null
      ? new Set<UserId>()
      : await projectMuteRepo.listRecipientsMutingProject(
          orgId,
          projectId,
          recipientIds,
        );

  const rows = [];

  for (const recipientId of recipientIds) {
    if (recipientId === payload.actorId) continue;

    const preference = await preferenceRepo.getPreference(
      orgId,
      recipientId,
      kind,
    );
    let channels = resolveChannels(preference, flags);

    if (mutedBy.has(recipientId)) {
      if (!PERSONAL_KINDS.has(kind)) continue;
      channels = channels.filter((channel) => channel !== "email");
    }
    if (channels.length === 0) continue;

    rows.push({
      orgId,
      recipientId,
      kind,
      title: payload.title,
      body: payload.body,
      href: payload.href,
      actorId: payload.actorId,
      projectId,
      channels,
    });
  }

  return notificationRepo.insertNotifications(orgId, rows);
}

/**
 * Mutes a project for the actor alone: only the actor's own mute changes, and
 * the actor must be able to read the project. Muting twice is a no-op.
 */
export async function muteProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  await assertCanReadProject(actor, orgId, projectId);
  await projectMuteRepo.insertProjectMute(orgId, actor.userId, projectId);
}

/** Lifts the actor's own mute on a project. Unmuting an unmuted project is a no-op. */
export async function unmuteProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  await assertCanReadProject(actor, orgId, projectId);
  await projectMuteRepo.deleteProjectMute(orgId, actor.userId, projectId);
}

/** The projects the actor has muted in this org. */
export async function listMutedProjectIds(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly ProjectId[]> {
  assertOrgScope(actor, orgId);
  return projectMuteRepo.listMutedProjectIds(orgId, actor.userId);
}

/** The guard shared by mute and unmute: same rules as reading the project. */
async function assertCanReadProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  assertOrgScope(actor, orgId);
  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:read", projectResource(project));
}

